//
// pack_test -- kern/v3d_pack42.h (generated by tools/v3d/genpackets.py from Mesa's v3d_packet.xml) against
// kern/v3d_cl.h's hand-written V3D 4.2 packets, the ones that run on the Pi 4: every packet the kernel
// builds, with random values in its fields, must give the same bytes both ways. That validates the
// generator -- whose V3D 7.1 output (kern/v3d_pack71.h, the Pi 5) cannot be compared with a GPU here.
// Also: each field of every generated packet / record of both versions, set alone to all ones, sets
// exactly its bits (an address its top-aligned ones). sh tools/tests/run_v3d_cl_test.sh
//
// MIT licence (docs/LICENSING.md).
//
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <assert.h>
#include <kern/v3d_cl.h>
#include <kern/v3d_pack42.h>
#include <kern/v3d_pack71.h>

static int s_fail = 0, s_tests = 0;
static unsigned R (unsigned bits) { unsigned long long v = ((unsigned long long) rand () << 31) ^ (unsigned long long) rand (); return bits >= 32 ? (unsigned) v : (unsigned) (v & ((1ull << bits) - 1)); }
static float RF () { return (float) (rand () % 20001 - 10000) / 64.0f; }

template <class H> static void same (const char *what, const H &h, const unsigned char *g, unsigned glen)
{
	s_tests++;
	unsigned char b[64]; memcpy (b, &h, sizeof h);
	if (sizeof h != glen || memcmp (b, g, glen) != 0)
	{
		s_fail++;
		printf ("FAIL %s: hand-written %u bytes, generated %u\n  hand:", what, (unsigned) sizeof h, glen);
		for (unsigned i = 0; i < sizeof h; i++) printf (" %02x", b[i]);
		printf ("\n  gen: ");
		for (unsigned i = 0; i < glen; i++) printf (" %02x", g[i]);
		printf ("\n");
	}
}
