// ---- each field alone: exactly its bits, both versions (the generator's packing itself) ------------------------------
// the packet with the field at all ones, XORed with the packet with it at 0 (the other fields as they are, the
// minus-one ones too): exactly the field's bits
static bool bit (const unsigned char *b, unsigned i) { return (b[i / 8] >> (i % 8)) & 1; }
static void field_alone (const char *what, const unsigned char *zero, const unsigned char *ones, unsigned len, unsigned start, unsigned size)
{
	s_tests++;
	unsigned bad = 0;
	for (unsigned i = 0; i < len * 8; i++)
		if ((bit (zero, i) != bit (ones, i)) != (i >= start && i < start + size)) bad++;
	if (bad) { s_fail++; printf ("FAIL %s: %u bits wrong\n", what, bad); }
}
#define ALONE(V, T, F, START, SIZE, ONES) { unsigned char z[V##_##T##_length], c[V##_##T##_length]; struct V##_##T v; memset (&v, 0, sizeof v); \
	V##_##T##_pack (z, &v); ONES; V##_##T##_pack (c, &v); field_alone (#V " " #T "." #F, z, c, V##_##T##_length, START, SIZE); }
static float allOnesF () { unsigned u = 0xFFFFFFFFu; float f; memcpy (&f, &u, 4); return f; }

int main ()
{
	srand (3);
	for (int i = 0; i < 2000; i++) round_once ();
	// the generated packing, a field alone (a sample of every kind: uint, bool, address, float, minus one)
	ALONE (V3D42, TILE_COORDINATES, tile_row_number, 20, 12, v.tile_row_number = 0xFFF);
	ALONE (V3D71, TILE_BINNING_MODE_CFG, log2_tile_width, 16, 3, v.log2_tile_width = 7);
	ALONE (V3D71, TILE_BINNING_MODE_CFG, width_in_pixels, 40, 16, v.width_in_pixels = 1);	// (minus one: 1 - 1 = 0 against 0 - 1)
	ALONE (V3D71, GL_SHADER_STATE_RECORD, fragment_shader_code_address, 67, 29, v.fragment_shader_code_address = 0xFFFFFFF8u);
	ALONE (V3D71, CLIPPER_XY_SCALING, viewport_half_width_in_1_64th_of_pixel, 8, 32, v.viewport_half_width_in_1_64th_of_pixel = allOnesF ());
	ALONE (V3D71, TILE_RENDERING_MODE_CFG_RENDER_TARGET_PART1, base_address, 15, 11, v.base_address = 0x7FF);
	printf ("pack_test: %d of %d failed\n", s_fail, s_tests);
	return s_fail != 0;
}
